<script setup lang="ts">
import { computed, ref } from "vue";
import { useRoute, useRouter } from "vue-router";
import { ElMessage, ElMessageBox } from "element-plus";
import logo from "@/assets/logo/logo2.png";
type Project={projectId:string;projectCode:string;projectName:string;entitlementMode:"BALANCE"|"SUBSCRIPTION";status:string};
type ApiKey={apiKeyId:string;keyName:string;keyPrefix:string;status:"ENABLED"|"DISABLED"|"REVOKED";expiresAt:string|null};
type Usage={requestId:string;projectId:string;model:string;executionResult:string;deliveryResult:string;billingResult:string;createdAt:string};
const route=useRoute();const router=useRouter();const active=computed(()=>route.path.includes("usage")?"usage":"projects");
const projects=ref<Project[]>([{projectId:"proj-demo",projectCode:"DEMO",projectName:"智能问答示例",entitlementMode:"BALANCE",status:"ACTIVE"},{projectId:"proj-ops",projectCode:"OPS",projectName:"运营助手",entitlementMode:"SUBSCRIPTION",status:"ACTIVE"}]);
const keys=ref<ApiKey[]>([{apiKeyId:"key-demo",keyName:"开发环境",keyPrefix:"sk-ha-demo...",status:"ENABLED",expiresAt:null}]);
const usage=ref<Usage[]>([{requestId:"req-20260922-001",projectId:"proj-demo",model:"ha-chat",executionResult:"SUCCESS",deliveryResult:"DELIVERED",billingResult:"SETTLED",createdAt:"2026-09-22 09:42:18"}]);
const projectDialog=ref(false),keyDialog=ref(false),secret=ref("");const projectForm=ref({projectCode:"",projectName:"",entitlementMode:"BALANCE" as Project["entitlementMode"]});const keyForm=ref({keyName:"",expiresAt:""});
function createProject(){if(!projectForm.value.projectCode||!projectForm.value.projectName)return ElMessage.warning("请填写项目编码和名称");projects.value.push({projectId:`proj-${Date.now()}`,...projectForm.value,status:"ACTIVE"});projectDialog.value=false;projectForm.value={projectCode:"",projectName:"",entitlementMode:"BALANCE"};ElMessage.success("项目已创建")}
function createKey(){if(!keyForm.value.keyName)return ElMessage.warning("请填写 Key 名称");secret.value=`sk-ha-${Math.random().toString(36).slice(2,22)}`;keys.value.push({apiKeyId:`key-${Date.now()}`,keyName:keyForm.value.keyName,keyPrefix:`${secret.value.slice(0,10)}...`,status:"ENABLED",expiresAt:keyForm.value.expiresAt||null});keyDialog.value=false;keyForm.value={keyName:"",expiresAt:""}}
function copySecret(){navigator.clipboard?.writeText(secret.value);ElMessage.success("Secret 已复制")}async function revoke(row:ApiKey){await ElMessageBox.confirm("撤销后不可恢复，确定继续吗？","撤销 API Key",{type:"warning"});row.status="REVOKED"}
</script>
<template><div class="ai-shell"><header class="ai-header"><div class="brand"><img :src="logo" alt="智行官"><span>HA AI</span></div><span class="header-caption">企业 AI 聚合服务平台</span></header><div class="ai-body"><aside class="ai-nav"><button :class="{active:active==='projects'}" @click="router.push('/ai/projects')">项目与 API Key</button><button :class="{active:active==='usage'}" @click="router.push('/ai/usage')">调用记录</button></aside><main class="ai-content"><template v-if="active==='projects'"><div class="page-heading"><div><h1>项目</h1><p>管理项目及其 API Key 访问凭证</p></div><el-button type="primary" @click="projectDialog=true">创建项目</el-button></div><section v-for="project in projects" :key="project.projectId" class="project-section"><div class="section-heading"><div><h2>{{project.projectName}}</h2><span class="muted">{{project.projectCode}} · {{project.entitlementMode}}</span></div><el-tag>{{project.status}}</el-tag></div><el-table :data="keys" stripe><el-table-column prop="keyName" label="Key 名称"/><el-table-column prop="keyPrefix" label="Key 前缀"/><el-table-column prop="status" label="状态"><template #default="{row}"><el-tag :type="row.status==='ENABLED'?'success':row.status==='REVOKED'?'danger':'info'">{{row.status}}</el-tag></template></el-table-column><el-table-column prop="expiresAt" label="过期时间"><template #default="{row}">{{row.expiresAt||'永不过期'}}</template></el-table-column><el-table-column label="操作" width="160"><template #default="{row}"><el-button v-if="row.status!=='REVOKED'" link type="danger" @click="revoke(row)">撤销</el-button></template></el-table-column></el-table><el-button class="add-key" text type="primary" @click="keyDialog=true">+ 创建 API Key</el-button></section></template><template v-else><div class="page-heading"><div><h1>调用记录</h1><p>查看 AI 调用的执行、交付与计费结果</p></div></div><el-table :data="usage" stripe><el-table-column prop="requestId" label="请求 ID" min-width="180"/><el-table-column prop="projectId" label="项目 ID"/><el-table-column prop="model" label="模型"/><el-table-column prop="executionResult" label="执行结果"/><el-table-column prop="deliveryResult" label="交付结果"/><el-table-column prop="billingResult" label="计费结果"/><el-table-column prop="createdAt" label="创建时间" min-width="170"/></el-table></template></main></div><el-dialog v-model="projectDialog" title="创建项目" width="460px"><el-form label-position="top"><el-form-item label="项目编码"><el-input v-model="projectForm.projectCode"/></el-form-item><el-form-item label="项目名称"><el-input v-model="projectForm.projectName"/></el-form-item><el-form-item label="权益模式"><el-select v-model="projectForm.entitlementMode" style="width:100%"><el-option label="余额" value="BALANCE"/><el-option label="订阅" value="SUBSCRIPTION"/></el-select></el-form-item></el-form><template #footer><el-button @click="projectDialog=false">取消</el-button><el-button type="primary" @click="createProject">保存</el-button></template></el-dialog><el-dialog v-model="keyDialog" title="创建 API Key" width="460px"><el-form label-position="top"><el-form-item label="Key 名称"><el-input v-model="keyForm.keyName"/></el-form-item><el-form-item label="过期时间（可选）"><el-date-picker v-model="keyForm.expiresAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" style="width:100%"/></el-form-item></el-form><template #footer><el-button @click="keyDialog=false">取消</el-button><el-button type="primary" @click="createKey">创建</el-button></template></el-dialog><el-dialog :model-value="Boolean(secret)" title="Secret 仅展示一次" width="520px" @close="secret=''" ><p class="secret-warning">请立即复制 Secret。关闭后将无法再次查看。</p><el-input :model-value="secret" readonly><template #append><el-button @click="copySecret">复制</el-button></template></el-input></el-dialog></div></template>
<style scoped>.ai-shell{min-height:100vh;background:#f5f7fa;color:#1f2937}.ai-header{height:64px;background:#fff;border-bottom:1px solid #e7ebf0;display:flex;align-items:center;padding:0 28px;gap:20px}.brand{display:flex;align-items:center;gap:14px;font-size:18px;font-weight:600}.brand img{width:140px;height:auto}.header-caption,.muted{color:#8491a5;font-size:13px}.ai-body{display:flex;min-height:calc(100vh - 64px)}.ai-nav{width:220px;background:#fff;padding:24px 14px;border-right:1px solid #e7ebf0}.ai-nav button{width:100%;padding:12px 14px;border:0;background:transparent;text-align:left;border-radius:6px;color:#526074;cursor:pointer}.ai-nav button.active{background:#edf4ff;color:#2868d8;font-weight:600}.ai-content{padding:34px 42px;flex:1;max-width:1280px}.page-heading,.section-heading{display:flex;align-items:center;justify-content:space-between}.page-heading{margin-bottom:28px}.page-heading h1,.section-heading h2{margin:0 0 7px}.page-heading p{margin:0;color:#8491a5}.project-section{background:#fff;border:1px solid #e7ebf0;border-radius:8px;padding:22px;margin-bottom:18px}.section-heading{margin-bottom:18px}.section-heading h2{font-size:17px}.add-key{margin-top:14px}.secret-warning{color:#b45309;background:#fff7ed;padding:12px;border-radius:4px}@media(max-width:768px){.ai-nav{width:156px}.ai-content{padding:24px 16px}.header-caption{display:none}.brand img{width:118px}}</style>
